-- Queer Atlas: verified queer and queer-friendly electronic events, Batch 5.
-- Countries: Canada, Mexico, Colombia, Brazil and Argentina. Researched 2026-08-29.
-- Dates and queer/inclusion claims are source-backed; uncertain future venues remain TBA.
-- Source data contains no vibe_tags; UPDATE and INSERT force ARRAY[]::text[].

begin;

alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists ticket_url text;

with src as (
  select * from jsonb_to_recordset($qa_americas_batch5_events$
[
{"name":"Toronto Queer Film Festival 2026","aliases":["TQFF 2026","10th Toronto Queer Film Festival"],"city":"toronto","date":"2026-10-14","start_date":"2026-10-14","end_date":"2026-10-18","description":"Toronto Queer Film Festival marks ten years with five days of independent queer cinema, performance, artist exchange and activist screen culture.","link":"https://torontoqueerfilmfest.com/","ticket_url":"https://torontoqueerfilmfest.com/","location":"Multiple announced venues, Toronto, Ontario, Canada","lat":43.6532,"lng":-79.3832,"vibe":"artist-led queer cinema gathering pairing radical film with conversation and performance","intel":{"entry_wait":"The detailed schedule and booking links are released closer to the festival; reserve opening, cabaret and limited-capacity screenings promptly.","best_arrival":"Use the final venue schedule and arrive before each listed seating time, allowing transfer time between downtown programme locations.","crowd_mix":"Queer and trans filmmakers, artists, activists, students, independent-cinema audiences and Toronto community members form the core public.","dress_code":"No festival-wide requirement applies; comfortable cinema clothing works by day and expressive looks suit cabaret or evening events.","host_inclusivity":"TQFF is an artist-led queer festival foregrounding independent, activist and community-rooted moving-image work.","source_urls":["https://torontoqueerfilmfest.com/"],"research_status":"official_dates_edition_and_queer_mission_verified","updated_at":"2026-08-29T00:00:00Z"}},
