{"name":"Canada Pride 2027 Halifax","aliases":["Halifax Canada Pride 2027","Canada Pride Halifax 2027"],"city":"halifax","date":"2027-07-15","start_date":"2027-07-15","end_date":"2027-07-25","description":"Canada's national 2SLGBTQIA+ celebration comes to Atlantic Canada with Halifax Pride, adding a human-rights conference, parade, concerts, drag, arts and national exchange.","link":"https://www.canadapride.ca/faq","ticket_url":"https://www.canadapride.ca/","location":"Multiple venues and city-centre parade route, Halifax, Nova Scotia, Canada","lat":44.6488,"lng":-63.5752,"vibe":"historic national Pride gathering combining rights work, Atlantic hospitality and large-scale celebration","intel":{"entry_wait":"Public events and the parade will coexist with ticketed shows and conference registration; monitor official releases from early 2027.","best_arrival":"Plan from the final eleven-day calendar and reach parade or headline-event assembly points early because Halifax expects national attendance.","crowd_mix":"2SLGBTQIA+ communities, Pride organisations, advocates, artists, families and visitors from across Canada and abroad gather.","dress_code":"No festival-wide code applies; expressive Pride looks, comfortable walking shoes and Atlantic-weather layers are practical.","host_inclusivity":"Canada Pride is the national 2SLGBTQIA+ gathering and Halifax Pride publishes community, rights and cultural programming at its centre.","source_urls":["https://www.canadapride.ca/faq","https://www.canadapride.ca/"],"research_status":"official_dates_host_national_scope_and_core_programme_verified","updated_at":"2026-08-29T00:00:00Z"}},

{"name":"Leather Fever Puerto Vallarta 2026","aliases":["Leather Fever 2026","STUDS Leather Fever 2026"],"city":"puerto_vallarta","date":"2026-11-19","start_date":"2026-11-19","end_date":"2026-11-22","description":"STUDS hosts a four-day bear, leather, kink and pup gathering with themed nights, fashion, title contests and adult community programming in Zona Romántica.","link":"https://gaypv.com/event-calendar/bear-and-leather/leather-fever/?gde=2026-11-19","ticket_url":"https://www.studsbarpv.com.mx/leather-fever-2026","location":"STUDS Bear & Leather Bar, Basilio Badillo 283, Zona Romántica, Puerto Vallarta, Jalisco, Mexico","lat":20.6025,"lng":-105.2344,"vibe":"men-centred leather and kink weekend pairing community ritual with playful adult nightlife","intel":{"entry_wait":"Purchase the appropriate pass in advance, carry valid 18+ identification and review which programme items are men-only or clothing optional.","best_arrival":"Collect credentials before the first desired event and arrive early for contests or limited-capacity nights inside the compact bar.","crowd_mix":"Bears, cubs, leather men, pups, kink communities and international gay visitors form the main audience.","dress_code":"Leather, fetish, underwear, jockstrap or pup gear fits themed sessions; ordinary casual clothing is accepted on many standard bar nights.","host_inclusivity":"STUDS explicitly serves bear and leather communities while publishing adult age, themed-dress and event-specific access expectations.","source_urls":["https://gaypv.com/event-calendar/bear-and-leather/leather-fever/?gde=2026-11-19","https://www.studsbarpv.com.mx/"],"research_status":"official_host_venue_and_secondary_exact_dates_verified","updated_at":"2026-08-29T00:00:00Z"}},
{"name":"Brawny Bear Weekend 2026","aliases":["Brawny Bear Puerto Vallarta 2026"],"city":"puerto_vallarta","date":"2026-11-19","start_date":"2026-11-19","end_date":"2026-11-22","description":"Brawny Bear Weekend spans Mantamar, Industry and One Six One with four pool parties, beach dancing, ten international DJs and themed bear nightlife.","link":"https://brawnybearweekend.com/","ticket_url":"https://brawnybearweekend.com/events","location":"Mantamar Beach Club, Industry Nightclub and One Six One, Puerto Vallarta, Jalisco, Mexico","lat":20.5947,"lng":-105.2395,"vibe":"destination bear circuit weekend flowing from oceanfront pools into high-energy house nights","intel":{"entry_wait":"Choose a weekend or individual-event pass before travel; headline pool and harness parties can reach capacity despite the multi-venue format.","best_arrival":"Check in before Thursday programming and reach pool parties near opening to secure a comfortable base before peak afternoon crowds.","crowd_mix":"Bears, cubs, admirers, gay travellers, circuit dancers and friends arrive from Mexico, North America and beyond.","dress_code":"Poolwear by day and underwear, harness or leather styling for named theme nights; review each event before packing.","host_inclusivity":"The weekend is purpose-built for LGBTQ+ bear communities by established gay nightlife and beachfront venue partners.","source_urls":["https://brawnybearweekend.com/","https://brawnybearweekend.com/events","https://gaypv.com/event-calendar/bear-and-leather/brawny-bear-weekend/?gde=2026-11-19"],"research_status":"official_event_scope_and_verified_dates_venues_lineup_format","updated_at":"2026-08-29T00:00:00Z"}},
